#ifndef SCAMP_FIB_H
#define SCAMP_FIB_H

#include "scamptrie_base.h"
#include <vector>

/* Live forwarding table: a plain binary trie over the 128 address bits.
   Puts are last-write-wins, lookups are exact longest-prefix matches and
   the same structure answers bounded lookups used for image BMP fields. */
class LiveFib {
public:
    LiveFib() { nodes_.push_back(Node()); }

    void put(u128_t addr, int len, uint32_t hop);
    nexthop_t lookup(u128_t addr) const { return lookup_bounded(addr, 128); }
    nexthop_t lookup_bounded(u128_t addr, int maxlen) const;
    void enumerate(std::vector<ScampPrefix>& out) const;
    size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }

private:
    struct Node {
        int32_t ch[2];
        uint32_t hop;
        Node() { ch[0] = ch[1] = -1; hop = SCAMP_BMP_NULL; }
    };
    std::vector<Node> nodes_;
    size_t count_ = 0;

    void walk(int idx, int depth, u128_t acc, std::vector<ScampPrefix>& out) const;
};

#endif /* SCAMP_FIB_H */
