cat > src/fib.cpp << 'EOF'
#include "fib.h"

void LiveFib::put(u128_t addr, int len, uint32_t hop) {
    if (len < 0) len = 0;
    if (len > 128) len = 128;
    addr = scamp_mask(addr, len);
    int idx = 0;
    for (int d = 0; d < len; ++d) {
        int b = static_cast<int>((addr >> (127 - d)) & 1u);
        int nx = nodes_[idx].ch[b];
        if (nx < 0) {
            nx = static_cast<int>(nodes_.size());
            nodes_[idx].ch[b] = nx;
            nodes_.push_back(Node());
        }
        idx = nx;
    }
    if (nodes_[idx].hop == SCAMP_BMP_NULL) ++count_;
    nodes_[idx].hop = hop;
}

nexthop_t LiveFib::lookup_bounded(u128_t addr, int maxlen) const {
    if (maxlen < 0) return LPM_INVALID_NH;
    if (maxlen > 128) maxlen = 128;
    uint32_t best = nodes_[0].hop;               /* depth 0 prefix */
    int idx = 0;
    for (int d = 0; d < maxlen; ++d) {
        int b = static_cast<int>((addr >> (127 - d)) & 1u);
        int nx = nodes_[idx].ch[b];
        if (nx < 0) break;
        idx = nx;
        if (nodes_[idx].hop != SCAMP_BMP_NULL) best = nodes_[idx].hop;
    }
    if (best == SCAMP_BMP_NULL) return LPM_INVALID_NH;
    return static_cast<nexthop_t>(best);
}

void LiveFib::walk(int idx, int depth, u128_t acc, std::vector<ScampPrefix>& out) const {
    if (nodes_[idx].hop != SCAMP_BMP_NULL) {
        ScampPrefix p;
        p.addr = scamp_mask(acc, depth);
        p.len = static_cast<uint8_t>(depth);
        p.hop = nodes_[idx].hop;
        out.push_back(p);
    }
    if (depth >= 128) return;
    for (int b = 0; b < 2; ++b) {
        int nx = nodes_[idx].ch[b];
        if (nx < 0) continue;
        u128_t nacc = b ? (acc | (static_cast<u128_t>(1) << (127 - depth))) : acc;
        walk(nx, depth + 1, nacc, out);
    }
}

void LiveFib::enumerate(std::vector<ScampPrefix>& out) const {
    out.clear();
    out.reserve(count_);
    walk(0, 0, 0, out);
}
